bool isTrackVisible(String path) {
  if (!isMounted()) return false;
  final rowContext = rowKeys[path]?.currentContext;
  if (rowContext == null) return false;

  final rowBox = rowContext.findRenderObject();
  if (rowBox is! RenderBox || !rowBox.hasSize) return false;

  final viewportContext = listViewKey.currentContext;
  if (viewportContext == null) return false;

  final viewportBox = viewportContext.findRenderObject();
  if (viewportBox is! RenderBox || !viewportBox.hasSize) return false;

  final viewportRect =
      viewportBox.localToGlobal(Offset.zero) & viewportBox.size;
  final rowRect = rowBox.localToGlobal(Offset.zero) & rowBox.size;
  return rowRect.overlaps(viewportRect);
}

